Nat4	loadPersistents_List_20_Window(V_Environment environment);
Nat4	loadPersistents_List_20_Window(V_Environment environment)
{
	V_Value tempPersistent = NULL;
	V_Dictionary dictionary = environment->persistentsTable;

	tempPersistent = create_persistentNode("List Window/Toolbar",NULL,environment);
	add_node(dictionary,tempPersistent->objectName,tempPersistent);

	return kNOERROR;

}

Nat4	load_List_20_Window(V_Environment environment);
Nat4	load_List_20_Window(V_Environment environment)
{

	loadClasses_List_20_Window(environment);
	loadUniversals_List_20_Window(environment);
	loadPersistents_List_20_Window(environment);
	return kNOERROR;

}

